        # Find where they differ
        min_len = min(len(inp), len(outp))
        for j in range(min_len):
            if inp[j] != outp[j]:
                print(f"  First difference at position {j}: '{inp[j]}' vs '{outp[j]}'")
                break
        else:
            # One string is prefix of other
            if len(inp) < len(outp):
                print(f"  Extended by: '{outp[len(inp):]}'")
            else:
                print(f"  Shortened to: '{inp[:len(outp)]}'")
    print()

